import { places } from './places.js';
import { archiveProjectRichBlocks } from './archiveProjectSources.js';

const travelMedia = places.map((place) => {
  const filename = String(place.img || '').split('/').pop();
  return {
    src: filename ? `/assets/travel/previews/${filename}.webp` : place.img,
    fullSrc: place.img,
    alt: place.en,
  };
});

const placeId = (place) => String(place.en || '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '');

const travelPlaceVariants = places.map((place) => ({
  id: `interactive.travels.place.${placeId(place)}`,
  title: place.label,
  description: `Open Henry’s Travels globe with ${place.label} selected.`,
  componentDescription: `The Travels globe focused on ${place.label}, with its pin selected and location photograph open. Visitors can still rotate the globe or choose another place.`,
  narrativeGuidance: `Use this focused city state when ${place.en} itself contributes material evidence. Pair it with a personal, study, work, research, project, or reflection source when explaining what the place meant to Henry.`,
  anchor: placeId(place),
  topics: [place.en, place.label, place.local].filter(Boolean),
  media: travelMedia.filter((item) => item.alt === place.en),
  entity: {
    kind: 'travel-place',
    id: placeId(place),
    focus_place: place,
  },
}));

