export function richBlockById(id) {
  for (const block of viewRichBlocks) {
    if (block.id === id) return block;
    const variant = (block.variants || []).find((item) => item.id === id);
    if (variant) {
      return {
        ...block,
        ...variant,
        variants: undefined,
        variantOf: block.id,
        componentFamily: block.componentFamily || block.id,
        entity: { ...(block.entity || {}), ...(variant.entity || {}) },
      };
    }
  }
  return undefined;
}
